import fs from "node:fs";
import path from "node:path";
import GithubSlugger from "github-slugger";

/** Generated by scripts/sync-docs.mjs from engg/docs (the source of truth). */
const CONTENT = path.join(process.cwd(), "content");

export interface SpecTab { id: string; label: string; title: string }
export interface Note { slug: string; file: string; label: string }
export interface DocsIndex { tabs: SpecTab[]; notes: Note[]; builtAt: string }

export type TaskStatus = "done" | "in_progress" | "blocked" | "todo" | "cut";
export interface Task { id: string; phase: string; title: string; status: TaskStatus; note?: string; ref?: string }
export interface Workstream { id: string; name: string; focus: string; tasks: Task[] }
export interface Tracker {
  updated: string;
  deadline: string;
  target_submit: string;
  statuses: Record<TaskStatus, string>;
  phases: Record<string, string>;
  workstreams: Workstream[];
}

export function getIndex(): DocsIndex {
  return JSON.parse(fs.readFileSync(path.join(CONTENT, "index.json"), "utf8"));
}

export function getSpecTab(id: string): string {
  return fs.readFileSync(path.join(CONTENT, "spec", `${id}.md`), "utf8");
}

export function getNote(slug: string): string {
  return fs.readFileSync(path.join(CONTENT, "notes", `${slug}.md`), "utf8");
}

export function getTracker(): Tracker {
  return JSON.parse(fs.readFileSync(path.join(CONTENT, "workstreams.json"), "utf8"));
}

// =====================
// Navigation
// =====================

export interface NavItem { href: string; label: string }
export interface NavGroup { title: string; items: NavItem[] }

/** Spec tabs grouped by what a reader is looking for. Every tab appears exactly once. */
const SPEC_GROUPS: { title: string; ids: string[] }[] = [
  { title: "Product", ids: ["overview", "products", "requirements", "screens"] },
  { title: "Build", ids: ["architecture", "data", "sponsors", "linking", "api", "database", "security"] },
  { title: "Delivery", ids: ["phases", "deliverables", "demo", "risks", "claude-code"] },
];

export function getNav(): NavGroup[] {
  const { tabs, notes } = getIndex();
  const byId = new Map(tabs.map((t) => [t.id, t]));
  const grouped = new Set(SPEC_GROUPS.flatMap((g) => g.ids));
  const groups: NavGroup[] = [
    { title: "Status", items: [{ href: "/docs/progress", label: "Progress" }] },
    ...SPEC_GROUPS.map((g) => ({
      title: g.title,
      items: g.ids.filter((id) => byId.has(id)).map((id) => ({ href: `/docs/${id}`, label: byId.get(id)!.label })),
    })),
  ];
  const leftover = tabs.filter((t) => !grouped.has(t.id));
  if (leftover.length) groups.push({ title: "More spec", items: leftover.map((t) => ({ href: `/docs/${t.id}`, label: t.label })) });
  groups.push({ title: "Project notes", items: notes.map((n) => ({ href: `/docs/notes/${n.slug}`, label: n.label })) });
  return groups;
}

/** Previous and next pages in sidebar order. */
export function getNeighbours(href: string): { prev?: NavItem; next?: NavItem } {
  const flat = getNav().flatMap((g) => g.items);
  const i = flat.findIndex((x) => x.href === href);
  return i < 0 ? {} : { prev: flat[i - 1], next: flat[i + 1] };
}

export interface Heading { id: string; text: string; depth: number }

/** Level-2/3 headings with the same ids rehype-slug assigns (github-slugger, document order). */
export function getHeadings(markdown: string): Heading[] {
  const slugger = new GithubSlugger();
  const out: Heading[] = [];
  let fenced = false;
  for (const line of markdown.split("\n")) {
    if (/^\s*(```|~~~)/.test(line)) fenced = !fenced;
    if (fenced) continue;
    const m = /^(#{1,6})\s+(.+?)\s*#*\s*$/.exec(line);
    if (!m) continue;
    const text = m[2]
      .replace(/\[([^\]]*)\]\([^)]*\)/g, "$1")
      .replace(/[`*_~]/g, "")
      .replace(/\\(.)/g, "$1")
      .trim();
    const id = slugger.slug(text);
    const depth = m[1].length;
    if (depth === 2 || depth === 3) out.push({ id, text, depth });
  }
  return out;
}

/** The public repository; links from a note to a file outside engg/docs open there. */
export const REPO_BLOB = "https://github.com/HudrTechLLC/nexus-chennai/blob/main";

/** Resolve a relative link from `from` (a path inside engg/docs) to a repo path, or null if it stays inside engg/docs. */
function outsideDocs(file: string, from: string): string | null {
  const parts = ["engg", "docs", ...from.split("/").slice(0, -1)];
  for (const seg of file.split("/")) {
    if (seg === "..") parts.pop();
    else if (seg && seg !== ".") parts.push(seg);
  }
  return parts[0] === "engg" && parts[1] === "docs" ? null : parts.join("/");
}

/**
 * Map links written for the repo (SPEC.md#x, DECISIONS.md, diagrams/...) to app routes.
 * `from` is the note's path inside engg/docs (e.g. "PATH2.md", "submission/FORM.md"); with it, a link
 * that leaves engg/docs (../../data/README.md) goes to that file on GitHub instead of a 404.
 */
export function rewriteHref(href: string | undefined, index: DocsIndex, from?: string): string | undefined {
  if (!href || /^(https?:|mailto:)/.test(href)) return href;
  const tabIds = new Set(index.tabs.map((t) => t.id));
  const [file, hash] = href.split("#");
  if (!file && hash) return tabIds.has(hash) ? `/docs/${hash}` : `#${hash}`;
  const repoPath = from ? outsideDocs(file, from) : null;
  if (repoPath) return `${REPO_BLOB}/${repoPath}${hash ? `#${hash}` : ""}`;
  const base = file.replace(/^(\.\.\/|\.\/)+/, "");
  if (/diagrams\/[^/]+\.svg$/.test(base)) return `/engg-docs/diagrams/${base.split("/").pop()}`;
  if (/(^|\/)SPEC\.md$/.test(base)) return hash && tabIds.has(hash) ? `/docs/${hash}` : "/docs/overview";
  if (base === "workstreams.json") return "/docs/progress";
  // Notes can live in subfolders (hackathon/, submission/); sibling links inside them use the bare file name.
  const note = index.notes.find((n) => n.file === base || n.file.endsWith(`/${base}`));
  if (note) return `/docs/notes/${note.slug}`;
  if (/(^|\/)validation\/README\.md$/.test(base)) return "/docs/notes/00-index";
  return href;
}
